INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (1, 'Pharmacology', 'Pain management', 'Before giving a scheduled dose of IV morphine, which assessment is the priority?', '["Respiratory rate and level of sedation","Pain rating on a 0–10 scale","Bowel sounds","Urine output over the last shift"]', 0, 'Opioids cause CNS and respiratory depression. Check respiratory rate and sedation first; increasing sedation usually comes before respiratory depression. Hold and notify if the patient is hard to rouse or respirations are below about 12/min (or per agency policy).', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (2, 'Pharmacology', 'Pain management', 'A patient on an opioid PCA is difficult to rouse and has a respiratory rate of 7/min. Which medication should the nurse anticipate?', '["Naloxone","Flumazenil","Acetylcysteine","Atropine"]', 0, 'Naloxone is an opioid antagonist that reverses opioid-induced respiratory depression. Flumazenil reverses benzodiazepines; acetylcysteine is the antidote for acetaminophen overdose.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (3, 'Pharmacology', 'Pain management', 'After naloxone reverses opioid-induced respiratory depression, why does the patient need continued close monitoring?', '["Naloxone''s effect can wear off before the opioid''s does, so respiratory depression can return","Naloxone commonly causes bradycardia for 24 hours","Naloxone causes delayed hypoglycemia","Naloxone must be followed by a dose of the opioid to prevent withdrawal"]', 0, 'Naloxone has a shorter duration of action than many opioids. Sedation and respiratory depression can recur as it wears off, so repeat doses may be needed.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (4, 'Pharmacology', 'Pain management', 'Which adverse effect of opioids does NOT lessen with ongoing use and should be prevented from the start of therapy?', '["Constipation","Nausea","Sedation","Respiratory depression"]', 0, 'Tolerance develops to most opioid effects, including nausea, sedation and respiratory depression, but not to constipation. A bowel regimen (fluids, fibre, stool softener/laxative) should start with opioid therapy.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (5, 'Pharmacology', 'Pain management', 'The usual maximum daily dose of acetaminophen for a healthy adult is:', '["4 g","1 g","8 g","650 mg"]', 0, 'For healthy adults the maximum is generally 4 g/day from all sources; lower limits apply with liver disease, regular alcohol use or low body weight. Overdose causes liver damage.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (6, 'Pharmacology', 'Pain management', 'A patient has taken a large overdose of acetaminophen. Which antidote should the nurse expect to be ordered?', '["Acetylcysteine","Naloxone","Vitamin K","Protamine sulfate"]', 0, 'Acetylcysteine protects the liver after acetaminophen overdose and works best when started early.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (7, 'Pharmacology', 'Pain management', 'Which teaching point is most important for a patient starting regular ibuprofen?', '["Take it with food and report black, tarry stools","Take it on an empty stomach for faster effect","It is safe to combine with other NSAIDs for stronger relief","Expect mild ringing in the ears as a normal effect"]', 0, 'NSAIDs irritate the GI tract and can cause ulcers and bleeding. Taking them with food reduces irritation; black, tarry stools may indicate GI bleeding and must be reported. Combining NSAIDs increases risk.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (8, 'Pharmacology', 'Pain management', 'A patient using patient-controlled analgesia (PCA) asks whether family members can press the button while the patient sleeps. The best response is:', '["Only you should press the button, because it protects you from getting too much medication","Yes, family can press it whenever you look uncomfortable","Only the nurse can press the button","Family can press it once per hour"]', 0, 'PCA is safe because a sedated patient stops pressing the button. ''PCA by proxy'' bypasses this safety feature and can cause overdose.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (9, 'Pharmacology', 'Sedatives & hypnotics', 'Which medication reverses benzodiazepine overdose?', '["Flumazenil","Naloxone","Physostigmine","Glucagon"]', 0, 'Flumazenil is a benzodiazepine receptor antagonist. Watch for seizures, especially in long-term benzodiazepine users, and for re-sedation.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (10, 'Pharmacology', 'Sedatives & hypnotics', 'A patient is prescribed lorazepam. Which statement shows the patient needs more teaching?', '["\"A glass of wine at night will help it work better.\"","\"I won''t drive until I know how this affects me.\"","\"I shouldn''t stop taking it suddenly.\"","\"It may make me drowsy.\""]', 0, 'Alcohol adds to the CNS depression of benzodiazepines and can cause dangerous sedation and respiratory depression. The other statements are correct.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (11, 'Pharmacology', 'Sedatives & hypnotics', 'Why should a benzodiazepine taken long-term not be stopped abruptly?', '["Withdrawal can cause anxiety, insomnia, tremors and seizures","The drug will build up to toxic levels","It causes severe hypertension crisis with certain foods","It permanently damages GABA receptors"]', 0, 'Physical dependence develops with long-term use. Abrupt withdrawal can cause rebound anxiety, insomnia, tremor and seizures, so doses are tapered.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (12, 'Pharmacology', 'Sedatives & hypnotics', 'Which is the greatest safety concern when an older adult takes a benzodiazepine for sleep?', '["Falls related to sedation, confusion and impaired balance","Hypertension","Weight gain","Hyperglycemia"]', 0, 'Older adults are more sensitive to benzodiazepines and clear them more slowly, increasing daytime sedation, confusion and falls.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (13, 'Pharmacology', 'Sedatives & hypnotics', 'A patient taking zolpidem reports finding food wrappers in the morning with no memory of eating. The nurse should:', '["Report it, since complex sleep behaviours are a serious adverse effect","Reassure the patient this is expected and harmless","Advise taking the dose earlier in the evening","Advise taking it with a small snack"]', 0, 'Zolpidem can cause complex sleep behaviours (sleep-walking, sleep-eating, sleep-driving) that may be dangerous. These should be reported and usually mean stopping the drug.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (14, 'Pharmacology', 'Psychotherapeutics', 'A patient started an SSRI 5 days ago and says it isn''t working. The best response is:', '["\"It usually takes several weeks to feel the full benefit, so keep taking it as prescribed.\"","\"You should ask to have the dose doubled.\"","\"Stop it and try a different medication.\"","\"It should have worked within 24 hours.\""]', 0, 'Antidepressants typically take a few weeks for noticeable improvement and longer for full effect. Patients should keep taking them and not stop suddenly.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (15, 'Pharmacology', 'Psychotherapeutics', 'A patient taking an SSRI is also given tramadol. Which findings suggest serotonin syndrome?', '["Agitation, fever, sweating, tachycardia and muscle twitching","Bradycardia, hypothermia and lethargy","Hypoglycemia and tremor only","Dry cough and rash"]', 0, 'Serotonin syndrome includes mental status changes (agitation, confusion), autonomic instability (fever, sweating, tachycardia) and neuromuscular signs (tremor, hyperreflexia, clonus). Risk rises when serotonergic drugs are combined.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (16, 'Pharmacology', 'Psychotherapeutics', 'A patient taking an MAOI should avoid which food?', '["Aged cheese","Fresh chicken","Steamed rice","Fresh apples"]', 0, 'Aged cheeses, cured meats, tap beer and other tyramine-rich foods can trigger a hypertensive crisis with MAOIs.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (17, 'Pharmacology', 'Psychotherapeutics', 'A patient on lithium has diarrhea, vomiting, a coarse hand tremor and confusion. The nurse suspects:', '["Lithium toxicity","A therapeutic response","Serotonin syndrome","Hypoglycemia"]', 0, 'These are signs of lithium toxicity. Hold the dose, notify the prescriber and expect a serum lithium level. Lithium has a narrow therapeutic range.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (18, 'Pharmacology', 'Psychotherapeutics', 'Which teaching helps prevent lithium toxicity?', '["Keep a normal salt and fluid intake and report vomiting, diarrhea or heavy sweating","Follow a low-sodium diet","Limit fluids to 1 litre a day","Take extra doses when feeling low"]', 0, 'Lithium is handled like sodium by the kidneys. Low sodium or dehydration (vomiting, diarrhea, sweating) increases lithium retention and the risk of toxicity.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (19, 'Pharmacology', 'Psychotherapeutics', 'A patient on haloperidol develops a high fever, severe muscle rigidity, confusion and an unstable blood pressure. The priority action is to:', '["Hold the antipsychotic and notify the prescriber immediately","Give the next dose on time","Offer a warm blanket","Encourage the patient to walk"]', 0, 'These are signs of neuroleptic malignant syndrome, a medical emergency. The antipsychotic is stopped and supportive care (cooling, fluids) started.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (20, 'Pharmacology', 'Psychotherapeutics', 'A patient on long-term antipsychotic therapy has repetitive lip smacking and tongue movements. This is most consistent with:', '["Tardive dyskinesia","Acute dystonia","Akathisia","Serotonin syndrome"]', 0, 'Tardive dyskinesia is a late extrapyramidal effect with involuntary movements of the mouth, face and limbs. It may be irreversible, so report it early.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (21, 'Pharmacology', 'Psychotherapeutics', 'A patient on clozapine reports a sore throat and fever. Why is this important?', '["It may signal agranulocytosis, a dangerous drop in white blood cells","It is an expected, harmless effect","It means the dose is too low","It indicates an allergy to food"]', 0, 'Clozapine can cause agranulocytosis. Blood counts are monitored regularly, and signs of infection must be reported right away.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (22, 'Pharmacology', 'Psychotherapeutics', 'Which monitoring is most important for a patient taking olanzapine long-term?', '["Weight, blood glucose and lipids","Peak flow readings","Hearing tests","Serum potassium only"]', 0, 'Atypical antipsychotics such as olanzapine can cause weight gain, high blood sugar and abnormal lipids (metabolic syndrome).', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (23, 'Pharmacology', 'Psychotherapeutics', 'Which statement about buspirone is correct?', '["It takes a few weeks to work and is not used as a PRN for acute anxiety","It works within minutes and is ideal for panic attacks","It is highly sedating and habit-forming","It must be tapered like a benzodiazepine"]', 0, 'Buspirone is a non-benzodiazepine anxiolytic with little sedation or dependence risk, but its effect builds over weeks, so it isn''t useful for acute anxiety.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (24, 'Pharmacology', 'Psychotherapeutics', 'Which side effects are expected with a tricyclic antidepressant such as amitriptyline?', '["Dry mouth, constipation, urinary retention and drowsiness","Diarrhea, excess salivation and frequent urination","Hypertension and weight loss","Insomnia and increased sweating only"]', 0, 'Tricyclics have strong anticholinergic effects and cause sedation and orthostatic hypotension. In overdose they are cardiotoxic, which matters for patients at risk of self-harm.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (25, 'Pharmacology', 'Psychotherapeutics', 'A 19-year-old has just started an antidepressant. What is especially important to monitor in the first weeks?', '["New or worsening suicidal thoughts or unusual changes in mood or behaviour","Serum calcium","Visual acuity","Daily weight"]', 0, 'Young people can have increased suicidal thinking early in antidepressant treatment, when energy may improve before mood does. Close monitoring is needed.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (26, 'Maternal/Child', 'Postpartum', 'On assessment, a postpartum patient''s fundus is boggy. The nurse''s first action is to:', '["Massage the fundus until it is firm","Notify the physician immediately","Give oxytocin without an order","Have the patient ambulate"]', 0, 'A boggy uterus is the most common cause of postpartum hemorrhage. Fundal massage (supporting the lower uterus) is the first step; notify if it stays boggy or bleeding is heavy.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (27, 'Maternal/Child', 'Postpartum', 'The fundus is firm but above the umbilicus and displaced to the right. What is the most likely cause?', '["A full bladder","Retained placenta","Normal involution","Uterine infection"]', 0, 'A distended bladder pushes the uterus up and to the side and can interfere with contraction. Have the patient void, then reassess.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (28, 'Maternal/Child', 'Postpartum', 'What is the expected order of lochia after birth?', '["Rubra, serosa, alba","Serosa, rubra, alba","Alba, serosa, rubra","Rubra, alba, serosa"]', 0, 'Lochia rubra (red) lasts about the first 3 days, serosa (pinkish-brown) to about day 10, then alba (yellowish-white).', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (29, 'Maternal/Child', 'Postpartum', 'After birth, the fundus normally descends by about:', '["1 cm (one fingerbreadth) per day","5 cm per day","1 cm per week","It does not descend until 6 weeks"]', 0, 'The fundus is near the umbilicus shortly after birth and descends about 1 cm per day, usually no longer palpable abdominally by about 2 weeks.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (30, 'Maternal/Child', 'Postpartum', 'An Rh-negative mother gives birth to an Rh-positive baby. What should the nurse anticipate?', '["Rh immune globulin given to the mother within 72 hours","Rh immune globulin given to the newborn","No treatment, since the baby is already born","A blood transfusion for the mother"]', 0, 'Rh immune globulin given to the mother within 72 hours prevents her from forming antibodies that could harm a future Rh-positive fetus.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (31, 'Maternal/Child', 'Complications', 'A patient receiving magnesium sulfate for preeclampsia has absent deep tendon reflexes and a respiratory rate of 10/min. The nurse should first:', '["Stop the infusion and notify the provider","Increase the infusion rate","Reassess in an hour","Give the next scheduled dose"]', 0, 'These are signs of magnesium toxicity. Stop the infusion and notify; calcium gluconate is the antidote.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (32, 'Maternal/Child', 'Newborn', 'Why is vitamin K given to newborns?', '["Newborns have low vitamin K, which raises the risk of bleeding","To prevent neonatal eye infection","To prevent jaundice","To boost the immune system"]', 0, 'Newborns have little vitamin K at birth (sterile gut and low transfer). An IM dose prevents vitamin K deficiency bleeding.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (33, 'Maternal/Child', 'Newborn', 'Which set of vital signs is within normal limits for a healthy term newborn at rest?', '["Heart rate 140, respirations 44","Heart rate 90, respirations 20","Heart rate 190, respirations 70","Heart rate 100, respirations 12"]', 0, 'Normal newborn heart rate is about 110–160 bpm and respirations about 30–60/min.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (34, 'Maternal/Child', 'Newborn', 'Jaundice is noticed in a newborn at 12 hours of age. The nurse should:', '["Report it promptly, because jaundice in the first 24 hours is considered pathologic","Reassure the parents it is normal physiologic jaundice","Place the baby by a sunny window","Stop breastfeeding"]', 0, 'Physiologic jaundice appears after 24 hours. Jaundice in the first 24 hours suggests a pathologic cause (such as hemolysis) and needs prompt assessment.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (35, 'Maternal/Child', 'Newborn', 'Which is NOT one of the five Apgar score components?', '["Blood pressure","Heart rate","Muscle tone","Colour"]', 0, 'Apgar assesses heart rate, respiratory effort, muscle tone, reflex irritability and colour at 1 and 5 minutes.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
INSERT INTO questions (id, course, topic, stem, options, answer, rationale, source, status, created_at, updated_at) VALUES (36, 'Maternal/Child', 'Newborn', 'A newborn of a diabetic mother is jittery and feeding poorly. The nurse should first:', '["Check the baby''s blood glucose","Wrap the baby more tightly","Recheck in 4 hours","Give a pacifier"]', 0, 'Jitteriness, poor feeding and temperature instability are signs of newborn hypoglycemia, which is common in infants of diabetic mothers. Check glucose and follow the feeding/treatment protocol.', 'Sample question (not from course decks)', 'approved', 1792725117143, 1792725117143);
